#include "ChunkSerializer.h"
#include "WorldCore/ChunkState.h"
FSerializedChunk UChunkSerializer::SerializeChunk(UChunkState* C)
{
 FSerializedChunk O;if(!C)return O;O.Coordinate=C->Coordinate;O.ExtensionCellPayloads=C->ExtensionCellPayloads;O.CellsPerAxis=FMath::Max(1,FMath::RoundToInt(FMath::Sqrt((float)C->Cells.Num())));O.LastUpdateDay=C->Metadata.LastUpdateDay;O.LastWeatherUpdateDay=C->Metadata.LastWeatherUpdateDay;O.LastSimulationTime=C->Metadata.LastSimulationTime;O.bIsInitialized=C->Metadata.bIsInitialized;O.ActivationMode=C->Metadata.ActivationMode;
 for(int32 I=0;I<C->Cells.Num();++I){const FChunkCell& X=C->Cells[I];FSerializedCell S;S.TerrainHeight=X.Terrain.Height;S.TerrainOriginalHeight=X.Terrain.OriginalHeight;S.TerrainDeformation=X.Terrain.Deformation;S.TerrainPermeability=X.Terrain.Permeability;S.TerrainMaterialID=X.Terrain.MaterialID;S.WaterVolume=X.Water.Volume;S.WaterLevel=X.Water.Level;S.WaterFlowRate=X.Water.FlowRate;S.WaterFlowDirection=X.Water.FlowDirection;S.bWaterSource=X.Water.bIsSource;S.bWaterFlowing=X.Water.bIsFlowing;S.SoilMoisture=X.SoilMoisture;S.SoilN=X.SoilNitrogen;S.SoilP=X.SoilPhosphorus;S.SoilK=X.SoilPotassium;S.SoilPH=X.SoilPH;S.Toxin=X.Chemistry.ToxinConcentration;S.Radioactivity=X.Chemistry.Radioactivity;S.ChemistryPH=X.Chemistry.pH;S.Pollution=X.Chemistry.Pollution;S.Biomass=X.Biomass.Biomass;S.BiomassHealth=X.Biomass.Health;S.BiomassMoisture=X.Biomass.MoistureContent;S.BiomassDecayRate=X.Biomass.DecayRate;S.SpeciesID=X.Biomass.SpeciesID;S.bBurning=X.Biomass.bIsBurning;
 const bool Default=FMath::IsNearlyZero(S.TerrainHeight)&&FMath::IsNearlyZero(S.TerrainOriginalHeight)&&FMath::IsNearlyZero(S.TerrainDeformation)&&FMath::IsNearlyEqual(S.TerrainPermeability,0.5f)&&S.TerrainMaterialID.IsNone()&&FMath::IsNearlyZero(S.WaterVolume)&&FMath::IsNearlyZero(S.WaterLevel)&&FMath::IsNearlyZero(S.WaterFlowRate)&&S.WaterFlowDirection.IsNearlyZero()&&!S.bWaterSource&&!S.bWaterFlowing&&FMath::IsNearlyEqual(S.SoilMoisture,0.3f)&&FMath::IsNearlyEqual(S.SoilN,50.0f)&&FMath::IsNearlyEqual(S.SoilP,30.0f)&&FMath::IsNearlyEqual(S.SoilK,40.0f)&&FMath::IsNearlyEqual(S.SoilPH,6.5f)&&FMath::IsNearlyZero(S.Toxin)&&FMath::IsNearlyZero(S.Radioactivity)&&FMath::IsNearlyEqual(S.ChemistryPH,7.0f)&&FMath::IsNearlyZero(S.Pollution)&&FMath::IsNearlyZero(S.Biomass)&&FMath::IsNearlyEqual(S.BiomassHealth,1.0f)&&FMath::IsNearlyEqual(S.BiomassMoisture,0.5f)&&FMath::IsNearlyEqual(S.BiomassDecayRate,0.02f)&&S.SpeciesID.IsNone()&&!S.bBurning;
 if(!Default)O.Cells.Add(I,S);
 }return O;
}
UChunkState* UChunkSerializer::DeserializeChunk(UObject* Outer,const FSerializedChunk& D)
{
 if(!Outer||D.CellsPerAxis<=0||D.CellsPerAxis>256)return nullptr;UChunkState* C=NewObject<UChunkState>(Outer);if(!C)return nullptr;C->Coordinate=D.Coordinate;C->Initialize(D.CellsPerAxis);C->ExtensionCellPayloads=D.ExtensionCellPayloads;C->Metadata.LastUpdateDay=D.LastUpdateDay;C->Metadata.LastWeatherUpdateDay=D.LastWeatherUpdateDay;C->Metadata.LastSimulationTime=D.LastSimulationTime;C->Metadata.bIsInitialized=D.bIsInitialized;C->Metadata.ActivationMode=D.ActivationMode;
 for(const auto& P:D.Cells){if(!C->Cells.IsValidIndex(P.Key))continue;const FSerializedCell& S=P.Value;FChunkCell& X=C->Cells[P.Key];X.Terrain.Height=S.TerrainHeight;X.Terrain.OriginalHeight=S.TerrainOriginalHeight;X.Terrain.Deformation=S.TerrainDeformation;X.Terrain.Permeability=S.TerrainPermeability;X.Terrain.MaterialID=S.TerrainMaterialID;X.Water.Volume=S.WaterVolume;X.Water.Level=S.WaterLevel;X.Water.FlowRate=S.WaterFlowRate;X.Water.FlowDirection=S.WaterFlowDirection;X.Water.bIsSource=S.bWaterSource;X.Water.bIsFlowing=S.bWaterFlowing;X.SoilMoisture=S.SoilMoisture;X.SoilNitrogen=S.SoilN;X.SoilPhosphorus=S.SoilP;X.SoilPotassium=S.SoilK;X.SoilPH=S.SoilPH;X.Chemistry.ToxinConcentration=S.Toxin;X.Chemistry.Radioactivity=S.Radioactivity;X.Chemistry.pH=S.ChemistryPH;X.Chemistry.Pollution=S.Pollution;X.Biomass.Biomass=S.Biomass;X.Biomass.Health=S.BiomassHealth;X.Biomass.MoistureContent=S.BiomassMoisture;X.Biomass.DecayRate=S.BiomassDecayRate;X.Biomass.SpeciesID=S.SpeciesID;X.Biomass.bIsBurning=S.bBurning;X.bHasWater=S.WaterVolume>0.001f;X.bHasFire=S.bBurning;X.bHasToxin=S.Toxin>0.001f;}
 return C;
}
